import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Load extremely bold font for the stamp
const { fontFamily: antonFamily } = loadAnton();



export type PermanentlyClosedProps = Record<string, any>;

const PermanentlyClosed: React.FC<PermanentlyClosedProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 5,
  text = "PERMANENTLY CLOSED",
  stampColor = "#D90429",
  rotationAngle = -12,
  borderThickness = 24,
  shakeIntensity = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height);

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timeline
  const startFrame = 5;
  const impactFrame = startFrame + 7; // The frame where the spring settles visually

  // Stamp "Slam" Physics
  const scale = spring({
    frame: frame - startFrame,
    fps,
    config: {
      damping: 12,
      mass: 1.5,
      stiffness: 180,
    },
    from: 5,
    to: 1,
  });

  const opacity = interpolate(frame, [startFrame, startFrame + 3], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Screen shake triggered right at impact
  // Input arrays MUST be strictly increasing
  const shakeX = interpolate(
    frame,
    [impactFrame, impactFrame + 2, impactFrame + 4, impactFrame + 6, impactFrame + 8],
    [0, -shakeIntensity, shakeIntensity, -shakeIntensity * 0.5, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const shakeY = interpolate(
    frame,
    [impactFrame, impactFrame + 3, impactFrame + 5, impactFrame + 7, impactFrame + 9],
    [0, shakeIntensity, -shakeIntensity, shakeIntensity * 0.5, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Subtle zoom out after slam for dynamic continuous movement
  const continuousScale = interpolate(
    frame,
    [impactFrame, impactFrame + fps * durationInSeconds],
    [1, 0.95],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const finalScale = scale * continuousScale;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `translate(${shakeX}px, ${shakeY}px)`,
        }}
      >
        <div
          style={{
            transform: `scale(${finalScale}) rotate(${rotationAngle}deg)`,
            opacity,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            flexDirection: "column",
            border: `${borderThickness}px solid ${stampColor}`,
            padding: `${s * 0.05}px ${s * 0.08}px`,
            borderRadius: `${borderThickness * 0.5}px`,
            position: "relative",
            maxWidth: width * 0.8,
            boxSizing: "border-box",
            // Inner outline simulating a double-line rubber stamp
            outline: `${Math.max(2, borderThickness * 0.25)}px solid ${stampColor}`,
            outlineOffset: `-${borderThickness * 1.5}px`,
          }}
        >
          <h1
            style={{
              fontFamily: antonFamily,
              color: stampColor,
              fontSize: s * 0.18,
              lineHeight: 1,
              margin: 0,
              textAlign: "center",
              textTransform: "uppercase",
              letterSpacing: `${s * 0.01}px`,
              textShadow: `0px ${s * 0.005}px ${s * 0.02}px rgba(0,0,0,0.3)`,
              wordWrap: "break-word",
            }}
          >
            {text}
          </h1>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PermanentlyClosed;